create or replace function public.job_completion_dates() returns table (job_id uuid, completed_at timestamptz) language sql stable security definer set search_path to 'public' as $fn$ with ev as (select e.job_id, min(e.changed_at) at from public.job_stage_events e join public.job_stages t on t.key = e.to_stage and t.is_complete left join public.job_stages f on f.key = e.from_stage where e.from_stage is not null and not coalesce(f.is_complete, false) group by e.job_id), lg as (select distinct on (r.job_id) r.job_id, (r.date_completed::timestamp at time zone 'America/New_York') at from public.completion_log_rows r join public.jobs j on j.id = r.job_id where r.match_status in ('matched', 'manual') and r.date_completed is not null order by r.job_id, (abs(coalesce(j.contract_amount, 0) - coalesce(r.contract_amount, 0)) < 1) desc, r.date_completed desc) select coalesce(lg.job_id, ev.job_id), coalesce(lg.at, ev.at) from lg full join ev on ev.job_id = lg.job_id where public.is_admin() $fn$;
comment on function public.job_completion_dates() is 'Admin only. Completion date per job: the Completion Log sheet''s DATE COMPLETED when the job has a matched row (the row whose contract matches the job, else the latest), otherwise the first stage-history move from a not-complete into a complete stage.';;
